def solve_n_queens(n):
    def can_place(pos, ocol, orow):
        for row in range(orow):
            col = pos[row]
            if col == ocol or abs(col - ocol) == abs(row - orow):
                return False
        return True

    def solve(orow, pos):
        if orow == n:
            return pos
        for ocol in range(n):
            if can_place(pos, ocol, orow):
                pos[orow] = ocol
                res = solve(orow + 1, pos)
                if res:
                    return res
        return None

    return solve(0, [-1] * n)

print(solve_n_queens(11))
